1	package httpapi
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"sync"
11		"testing"
12	
13		"github.com/cocosolocoder/signalroom/internal/events"
14		"github.com/cocosolocoder/signalroom/internal/metrics"
15	)
16	
17	type fakeMetricStorage struct {
18		mu       sync.Mutex
19		failNext bool
20		poisoned bool
21		batches  [][]metrics.Sample
22	
23		// stall, when non-nil, blocks one Append (with the metric store write
24		// lock held) until the channel is closed; stallEntered closes once that
25		// Append reaches the wait. armStall sets both up.
26		stall        chan struct{}
27		stallEntered chan struct{}
28	}
29	
30	// armStall makes the next Append block until the returned release channel is
31	// closed. The returned entered channel closes once that Append is waiting, so
32	// a test knows the batch is held mid commit.
33	func (f *fakeMetricStorage) armStall() (release, entered chan struct{}) {
34		release = make(chan struct{})
35		entered = make(chan struct{})
36		f.mu.Lock()
37		f.stall = release
38		f.stallEntered = entered
39		f.mu.Unlock()
40		return release, entered
41	}
42	
43	func (f *fakeMetricStorage) Append(batch []metrics.Sample) error {
44		f.mu.Lock()
45		stall := f.stall
46		entered := f.stallEntered
47		f.stall = nil
48		f.stallEntered = nil
49		f.mu.Unlock()
50		if stall != nil {
51			// Only the first Append blocks: the stalled submission still holds
52			// the metric store lock, so no other Append can reach here at once.
53			close(entered)
54			<-stall
55		}
56		f.mu.Lock()
57		defer f.mu.Unlock()
58		if f.failNext {
59			f.poisoned = true
60			f.failNext = false
61			return errors.New("simulated metric write failure")
62		}
63		f.batches = append(f.batches, append([]metrics.Sample(nil), batch...))
64		return nil
65	}
66	
67	func (f *fakeMetricStorage) Poisoned() bool {
68		f.mu.Lock()
69		defer f.mu.Unlock()
70		return f.poisoned
71	}
72	
73	func newMetricsServer(t *testing.T, store *metrics.Store, mstore *fakeMetricStorage) *httptest.Server {
74		t.Helper()
75		if store == nil {
76			store = metrics.NewStore()
77		}
78		if mstore == nil {
79			mstore = &fakeMetricStorage{}
80		}
81		tl := events.NewTimeline()
82		eventStore := &fakeStorage{cursorKey: []byte("test-cursor-key-0123456789ab")}
83		server := httptest.NewServer(NewHandler(tl, eventStore, eventStore, WithMetrics(store, mstore)))
84		t.Cleanup(server.Close)
85		return server
86	}
87	
88	func metricsDo(t *testing.T, server *httptest.Server, method, path, body string) (int, map[string]any) {
89		t.Helper()
90		var reader io.Reader
91		if body != "" {
92			reader = strings.NewReader(body)
93		}
94		req, err := http.NewRequest(method, server.URL+path, reader)
95		if err != nil {
96			t.Fatal(err)
97		}
98		if body != "" {
99			req.Header.Set("Content-Type", "application/json")
100		}
101		resp, err := http.DefaultClient.Do(req)
102		if err != nil {
103			t.Fatal(err)
104		}
105		defer resp.Body.Close()
106		raw, err := io.ReadAll(resp.Body)
107		if err != nil {
108			t.Fatal(err)
109		}
110		var out map[string]any
111		if err := json.Unmarshal(raw, &out); err != nil {
112			t.Fatalf("decode %q (%d): %v", raw, resp.StatusCode, err)
113		}
114		return resp.StatusCode, out
115	}
116	
117	func postSamples(t *testing.T, server *httptest.Server, body string) map[string]any {
118		t.Helper()
119		status, out := metricsDo(t, server, http.MethodPost, "/metrics", body)
120		if status >= 400 {
121			t.Fatalf("POST /metrics %d: %v", status, out)
122		}
123		return out
124	}
125	
126	func TestPostMetricsCreatedAndReplayed(t *testing.T) {
127		server := newMetricsServer(t, nil, nil)
128		body := `{"samples":[
129			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1},
130			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":2,"labels":{"env":"prod"}}
131		]}`
132		out := postSamples(t, server, body)
133		if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
134			t.Fatalf("initial: %v", out)
135		}
136	
137		// Retry with 1.0 numeric equivalence.
138		retry := `{"samples":[
139			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1.0},
140			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T18:00:01+08:00","value":2,"labels":{"env":"prod"}}
141		]}`
142		out = postSamples(t, server, retry)
143		if int(number(out["created"])) != 0 || int(number(out["replayed"])) != 2 {
144			t.Fatalf("retry: %v", out)
145		}
146	}
147	
148	func TestPostMetricsValidationAndConflict(t *testing.T) {
149		server := newMetricsServer(t, nil, nil)
150		postSamples(t, server, `{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`)
151	
152		cases := []struct {
153			name   string
154			body   string
155			status int
156		}{
157			{"empty array", `{"samples":[]}`, http.StatusBadRequest},
158			{"missing samples", `{}`, http.StatusBadRequest},
159			{"unknown field", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}],"x":1}`, http.StatusBadRequest},
160			{"blank id", `{"samples":[{"id":"  ","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusBadRequest},
161			{"negative value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":-1}]}`, http.StatusBadRequest},
162			{"string value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":"1"}]}`, http.StatusBadRequest},
163			{"bad time", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"nope","value":1}]}`, http.StatusBadRequest},
164			{"duplicate json field", `{"samples":[{"id":"s9","id":"s10","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusBadRequest},
165			{"changed content", `{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":5}]}`, http.StatusConflict},
166			{"series time clash", `{"samples":[{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusConflict},
167			{"in-batch dup id", `{"samples":[{"id":"d","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":1},{"id":"d","service":"gw","name":"requests","at":"2026-10-01T10:00:02Z","value":2}]}`, http.StatusConflict},
168		}
169		for _, tc := range cases {
170			status, out := metricsDo(t, server, http.MethodPost, "/metrics", tc.body)
171			if status != tc.status {
172				t.Fatalf("%s: want %d, got %d (%v)", tc.name, tc.status, status, out)
173			}
174			if out["error"] == "" {
175				t.Fatalf("%s: non-empty error required, got %v", tc.name, out)
176			}
177		}
